function netV151(acc={}){return typeof window.accountNetV141==='function'?window.accountNetV141(acc):Number(acc.saldoContaCentavos??(Number(acc.saldoCreditoCentavos||0)-Number(acc.dividaCentavos||0)))}
function signedV151(v){const n=Math.round(Number(v||0));return `${n<0?'-':''}${fmt(Math.abs(n))}`}
function normalizeHumanV151(v){return String(v||'').replaceAll('_',' ').replace(/\b\w/g,x=>x.toUpperCase())}
function methodLabelV151(v){const map={dinheiro:'Dinheiro',pix:'Pix',pix_manual:'Pix realizado na secretaria',pix_banco:'Pix bancário',pix_rede:'Pix Rede / Laranjinha',cartao:'Cartão',cartao_rede:'Cartão Rede / Laranjinha',maquininha:'Cartão na maquininha',checkout_infinitepay:'InfinitePay',saldo_conta:'Saldo da conta',saldo_e_checkout:'Saldo da conta + InfinitePay',saldo_e_pagamento:'Saldo da conta + pagamento presencial',credito_pre_pago:'Saldo da conta',conta_aluno:'Conta do aluno',secretaria:'Secretaria',cantina:'Cantina'};return map[String(v||'').toLowerCase()]||normalizeHumanV151(v)||'-'}
function statusLabelV151(v){const map={preparando_link:'Preparando link',erro_timeout:'Tempo excedido',aguardando_pagamento:'Aguardando pagamento',pago:'Pago',pago_com_saldo:'Pago com saldo da conta',reservado:'Reservado',confirmado:'Confirmado',pedido_confirmado:'Confirmado · aguarda entrega',pendente_entrega:'Aguardando entrega',em_andamento:'Em andamento',concluido:'Concluído',concluido_devolucoes:'Concluído com devoluções',entregue:'Entregue',aluno_ausente:'Aluno ausente — valor devolvido',ausente:'Aluno ausente — valor devolvido',nao_entregue:'Não entregue — valor devolvido',revisao:'Em revisão',cancelado_reserva:'Reserva expirada',nao_concluido:'Pagamento não concluído',erro_gerar_link:'Não foi possível gerar o pagamento',erro_sem_url:'Pagamento indisponível',pagamento_localizado_processando:'Pagamento localizado — processando',pagamento_localizado_aguardando_processamento:'Pagamento localizado — aguardando processamento',aguardando_producao:'Aguardando produção',reservado_estoque:'Reservado em estoque',enviado_fabrica:'Enviado para a fábrica',em_producao:'Em produção',pronto_retirada:'Pronto para retirada',cancelado:'Cancelado',cancelado_responsavel:'Cancelado pelo responsável',remarcado:'Remarcado',descartado_responsavel:'Descartada pelo responsável',substituido_nova_cobranca:'Substituída por nova cobrança',pago_descartado_creditado:'Pago depois do descarte — valor creditado'};return map[String(v||'').toLowerCase()]||normalizeHumanV151(v)||'-'}
function movementLabelV151(m={}){const k=String(m.subtipo||m.tipo||'').toLowerCase();const map={pagamento_checkout_infinitepay:'Pagamento confirmado pela InfinitePay',pagamento_pedido_cantina:'Pagamento do pedido da cantina',pagamento_pedido_farda:'Pagamento do fardamento',pagamento_pedido_em_revisao:'Pagamento recebido — pedido em revisão',pagamento_presencial:'Pagamento presencial',pagamento_venda_secretaria:'Pagamento da compra na secretaria',credito_secretaria:'Crédito adicionado na secretaria',entrada_conta_aluno:'Entrada na conta do aluno',pedido_cantina:'Pedido da cantina',pedido_farda:'Pedido de fardamento',venda_secretaria:'Compra realizada na secretaria',consumo:'Consumo na cantina',consumo_cantina:'Consumo na cantina',credito_ausencia:'Crédito por ausência',credito_nao_entrega:'Crédito por lanche não entregue',credito_convertido:'Crédito devolvido',ajuste_manual:'Ajuste realizado pela escola'};return map[k]||statusLabelV151(k||'Lançamento')}
function movementAmountV151(m={}){let v=Number(m.valorCentavos||0);if(['consumo','compra_farda','venda_conta'].includes(m.tipo)&&v>0)v=-v;return v}
function movementDescriptionV151(m={}){if(m.observacao)return esc(m.observacao);if(Array.isArray(m.itens)&&m.itens.length)return m.itens.map(x=>`${x.quantidade||1}× ${esc(x.nome||x.descricao||'Item')}`).join(', ');if(m.pedidoId)return `Pedido ${esc(m.pedidoId)}`;if(m.orderNsu)return `Pagamento ${esc(m.orderNsu)}`;return methodLabelV151(m.formaPagamento||m.origem)}
function statusBadgeV151(v){const s=String(v||'');const cls=['pago','confirmado','entregue','concluido','reservado_estoque','pronto_retirada'].includes(s)?'b-green':['aguardando_pagamento','pedido_confirmado','pendente_entrega','em_andamento','pago_com_saldo','reservado','aguardando_producao','em_producao'].includes(s)?'b-yellow':['nao_concluido','cancelado','cancelado_reserva','nao_entregue','aluno_ausente','ausente','revisao','concluido_devolucoes'].includes(s)?'b-red':'b-blue';return `<span class="badge ${cls}">${esc(statusLabelV151(s))}</span>`}
function datePtV151(v,withWeek=false){if(!v)return'-';try{return new Date(`${String(v).slice(0,10)}T12:00:00`).toLocaleDateString('pt-BR',withWeek?{weekday:'long',day:'2-digit',month:'2-digit'}:undefined)}catch(e){return v}}
function orderPeriodV151(o){return window.PiagetPortalUtils.orderPeriod(o,datePtV151,humanDate)}
function aggregateOrderV151(order,occ=[]){return window.PiagetPortalUtils.aggregateOrder(order,occ,statusLabelV151)}
