 $('#parentScreen').innerHTML=`<div class="parent-wrap"><div class="v151-parent-head"><div><h2>${esc(a.nome)}</h2><p style="margin:5px 0 0;opacity:.78">${esc(a.turma)} · Matrícula ${esc(a.matricula)}</p><div style="margin-top:9px">${statusBadgeV151(blocked?'cancelado':net<0?'aguardando_pagamento':'confirmado')} <span style="font-size:12px;opacity:.82;margin-left:5px">${esc(status)}</span></div></div><div class="v151-balance v156-balance-compact"><small>Saldo da conta ${infoButton('Saldo da conta','Valor positivo é crédito disponível. Valor negativo é saldo em aberto.')}</small><strong>${signedV151(net)}</strong><button type="button" class="v156-extrato-link" onclick="openParentMovementsV151()" aria-label="Ver extrato da conta">Ver extrato</button></div></div><div id="v151ParentNotice" class="v151-parent-notice"></div><div class="v151-parent-grid">${cards.map((c,i)=>`<button class="v151-menu-card" onclick="${c[3]}"><span class="ico">${c[0]}</span><strong>${esc(c[1])}</strong><span>${esc(c[2])}</span>${i===8?'<span id="parentAccessStatusClean" class="parent-access-status-clean"></span>':''}</button>`).join('')}</div></div>`;
 loadParentNoticeV151(a.id).catch(()=>{});loadParentAccessStatusClean(a.id).catch(()=>{});enhancePasswordFieldsV156?.();
