async function loadParentNoticeV151(id){
  const host=$('#v151ParentNotice');if(!host)return;
  try{
    const [p,c]=await Promise.all([db.collection('pagamentos_checkout').where('alunoId','==',id).get().catch(()=>({docs:[]})),db.collection('pedidos').where('alunoId','==',id).get().catch(()=>({docs:[]}))]);
    const pending=p.docs.map(d=>d.data()).filter(x=>['preparando_link','aguardando_pagamento'].includes(x.status)).length;
    const deliveries=c.docs.map(d=>d.data()).filter(x=>x.tipoPedido==='cantina'&&['confirmado','reservado'].includes(x.statusPedido)).length;
    host.innerHTML=`${pending?`<button class="alert warn v154-pending-alert" onclick="openParentPendingPaymentsV154()"><strong>${pending} pagamento(s) pendente(s).</strong> Toque para abrir.</button>`:''}${deliveries?`<button class="alert v156-program-alert" style="margin-top:${pending?8:0}px" onclick="openParentProgramsV156()"><strong>${deliveries} programação(ões) de lanche ativa(s).</strong><span>Ver programação →</span></button>`:''}`;
  }catch(e){host.innerHTML=''}
}
