function renderSecretaryItemsV151(){const st=state.v151Sale,host=$('#v151SaleItems');if(!host)return;if(st.operation==='adicionar_credito'){host.innerHTML='<div class="alert">Na próxima etapa, informe quanto foi recebido e a forma de pagamento.</div>';return}if(st.operation==='pedido_cantina_programado'){host.innerHTML='<div class="alert">Ao continuar, você abrirá o mesmo planejador de dia, semana e mês usado no portal. O pagamento será registrado presencialmente.</div>';return}const products=(state.products||[]).filter(p=>p.ativo!==false&&p.vendaSecretaria!==false);host.innerHTML=`<div class="card"><div class="card-head"><div class="card-title">Produtos da cantina</div></div><div class="card-body"><div class="v151-catalog">${products.map(p=>`<button class="product-btn ${p.combo?'combo':''}" onclick="addSecretaryProductV151('${p.id}')"><strong>${esc(p.nome)}</strong><span>${fmt(productPrice(p))}</span></button>`).join('')}</div></div></div><div class="actions" style="margin-top:10px"><button class="btn btn-light" onclick="addSecretaryUniformV151()">+ Adicionar fardamento</button></div><div class="card" style="margin-top:10px"><div class="card-head"><div class="card-title">Carrinho</div><strong>${fmt(secretarySaleTotalV151())}</strong></div><div class="card-body">${st.cart.length?st.cart.map((x,i)=>`<div class="v151-cart-line"><div><strong>${esc(x.nome)}</strong><div class="muted" style="font-size:11px">${x.tipo==='farda'?`${esc(x.tamanho)} ${esc(x.modelo||'')}`:esc(x.categoria||'Cantina')}</div></div><div><button class="btn btn-outline" onclick="changeSecretaryQtyV151(${i},-1)">−</button> <strong>${x.quantidade}</strong> <button class="btn btn-outline" onclick="changeSecretaryQtyV151(${i},1)">+</button></div><button class="btn btn-outline" onclick="removeSecretaryLineV151(${i})">Remover</button></div>`).join(''):'<div class="empty-soft">Carrinho vazio.</div>'}</div></div>`}
