function pendingExpiryV154(p){return p.tipo==='pedido_cantina'&&p.reservaExpiraEm?new Date(p.reservaExpiraEm).getTime():0}
function pendingStatusV154(p){const expired=pendingExpiryV154(p)>0&&pendingExpiryV154(p)<=Date.now()&&p.status!=='pago';if(expired)return'Reserva expirada';return statusLabelV151(p.status||'aguardando_pagamento')}
async function openParentPendingPaymentsV154(){
  const a=state.parentStudent;openModal('Pagamentos pendentes','<div class="v151-inline-loader">Carregando pagamentos...</div>');
  try{
    const snap=await db.collection('pagamentos_checkout').where('alunoId','==',a.id).get(),rows=snap.docs.map(d=>({id:d.id,...d.data()})).filter(p=>['preparando_link','aguardando_pagamento','erro_timeout','erro_gerar_link','erro_sem_url','pagamento_localizado_processando','pagamento_localizado_aguardando_processamento'].includes(p.status)).sort((x,y)=>String(y.criadoEm||'').localeCompare(String(x.criadoEm||''))).slice(0,30);
    $('#modalBody').innerHTML=rows.length?`<div class="v151-list">${rows.map(p=>{const expires=pendingExpiryV154(p),expired=expires>0&&expires<=Date.now(),canContinue=Boolean(p.checkoutUrl)&&!expired,canDiscard=['preparando_link','aguardando_pagamento','erro_timeout','erro_gerar_link','erro_sem_url'].includes(p.status);return`<div class="v154-payment-card"><div><strong>${esc(p.descricao||methodLabelV151(p.tipo))}</strong><div class="muted">${humanDate(p.criadoEm)} · ${fmt(p.totalCentavos||0)}</div><div style="margin-top:6px">${expired?'<span class="badge b-red">Reserva expirada</span>':statusBadgeV151(p.status)}</div>${expires&&!expired?`<div class="v154-countdown" data-expiry="${esc(p.reservaExpiraEm)}"></div>`:''}</div><div class="actions">${canContinue?`<button class="btn btn-primary" onclick="location.href='${esc(p.checkoutUrl)}'">Continuar pagamento</button>`:''}${p.status==='preparando_link'&&!p.checkoutUrl?`<button class="btn btn-light" onclick="openParentPendingPaymentsV154()">Atualizar</button>`:''}<button class="btn btn-outline" onclick="verifyParentPendingV154('${esc(p.orderNsu||p.id)}','${esc(p.transactionNsu||'')}','${esc(p.invoiceSlug||'')}')">Atualizar status</button>${canDiscard?`<button class="btn btn-red" onclick="discardParentPendingV155('${esc(p.orderNsu||p.id)}')">Descartar cobrança</button>`:''}${expired&&p.tipo==='pedido_cantina'?`<button class="btn btn-orange" onclick="closeModal();openParentOrderV151('semanal')">Refazer pedido</button>`:''}</div></div>`}).join('')}</div>`:'<div class="empty">Nenhum pagamento pendente.</div>';
    startPendingCountdownsV154();
  }catch(e){$('#modalBody').innerHTML=`<div class="alert danger">${esc(e.message)}</div>`}
}
function startPendingCountdownsV154(){document.querySelectorAll('.v154-countdown[data-expiry]').forEach(el=>{const tick=()=>{const ms=new Date(el.dataset.expiry).getTime()-Date.now();if(ms<=0){el.textContent='Reserva expirada';return}const m=Math.floor(ms/60000),s=Math.floor((ms%60000)/1000);el.textContent=`Reserva válida por ${String(m).padStart(2,'0')}:${String(s).padStart(2,'0')}`;setTimeout(tick,1000)};tick()})}
async function verifyParentPendingV154(orderNsu,transactionNsu='',invoiceSlug=''){try{const resp=await fetch('/api/verificar-pagamento',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({order_nsu:orderNsu,transaction_nsu:transactionNsu,slug:invoiceSlug})}),data=await resp.json().catch(()=>({}));if(!resp.ok)throw new Error(data.error||'Não foi possível atualizar o pagamento.');if(data.paid&&data.applicationPending){toast('Pagamento localizado. O pedido ainda está sendo processado.');return openParentPendingPaymentsV154()}toast(data.paid?'Pagamento confirmado e aplicado.':'Pagamento ainda não confirmado.');data.paid?renderParentPortal():openParentPendingPaymentsV154()}catch(e){appMessage(e.message)}}
async function discardParentPendingV155(orderNsu){
  const a=state.parentStudent;if(!a)return appMessage('Aluno não identificado.');
  const ok=await appConfirm('A cobrança sairá da lista de pendentes. Não utilize mais o link antigo. Se ele for pago depois, o valor será creditado na conta do aluno sem repetir o pedido.',{title:'Descartar cobrança?',confirmLabel:'Descartar cobrança',cancelLabel:'Manter cobrança',danger:true});
  if(!ok)return;
  try{
    const resp=await fetch('/api/descartar-cobranca',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({order_nsu:orderNsu,alunoId:a.id,descartadoPorNome:a.responsavelFinanceiro||'Responsável'})});
    const data=await resp.json().catch(()=>({}));if(!resp.ok)throw new Error(data.error||'Não foi possível descartar a cobrança.');
    toast(data.alreadyDiscarded?'A cobrança já estava descartada.':'Cobrança descartada.');openParentPendingPaymentsV154();
  }catch(e){appMessage(e.message)}
}
window.openParentPendingPaymentsV154=openParentPendingPaymentsV154;window.verifyParentPendingV154=verifyParentPendingV154;window.discardParentPendingV155=discardParentPendingV155;

