function stableHashV156(value){let h=2166136261;for(const ch of JSON.stringify(value||{})){h^=ch.charCodeAt(0);h=Math.imul(h,16777619)}return (h>>>0).toString(36)}
function balanceAttemptKeyV156(type,studentId,payload){return `vp_saldo_${type}_${studentId}_${stableHashV156(payload)}`}
function balanceAttemptV156(type,studentId,payload){const key=balanceAttemptKeyV156(type,studentId,payload);let saved=null;try{saved=JSON.parse(localStorage.getItem(key)||'null')}catch(e){}if(!saved?.id||Date.now()-Number(saved.createdAt||0)>15*60*1000){saved={id:`${type}_${studentId}_${Date.now()}_${Math.random().toString(36).slice(2,9)}`,createdAt:Date.now()};try{localStorage.setItem(key,JSON.stringify(saved))}catch(e){}}return saved.id}
function clearBalanceAttemptV156(type,studentId,payload){try{localStorage.removeItem(balanceAttemptKeyV156(type,studentId,payload))}catch(e){}}
async function openParentReceiptMenuV156(movementId,orderNsu=''){
 try{const [mSnap,cSnap]=await Promise.all([db.collection('movimentos_conta').doc(movementId).get(),orderNsu?db.collection('pagamentos_checkout').doc(orderNsu).get():Promise.resolve(null)]);if(!mSnap.exists)throw new Error('Movimentação não encontrada.');const m={id:mSnap.id,...mSnap.data()},c=cSnap?.exists?{id:cSnap.id,...cSnap.data()}:null;state.v156Receipt={movement:m,checkout:c};openModal('Comprovante',`<div class="v156-receipt-options">${c?.receiptUrl?`<a class="v156-receipt-option" href="${esc(c.receiptUrl)}" target="_blank" rel="noopener"><span>InfinitePay</span><strong>Comprovante da InfinitePay</strong></a>`:''}<button class="v156-receipt-option" onclick="downloadParentReceiptImageV156()"><span>Escola Piaget</span><strong>Comprovante em imagem</strong></button><button class="v156-receipt-option" onclick="downloadParentReceiptPdfV156()"><span>Escola Piaget</span><strong>Comprovante em PDF</strong></button></div>`)}catch(e){appMessage(e.message)}
}
function receiptLinesV156(){const {movement:m,checkout:c}=state.v156Receipt||{};if(!m)return null;return{title:movementLabelV151(m),student:state.parentStudent?.nome||c?.alunoNome||'',matricula:state.parentStudent?.matricula||c?.matricula||'',date:m.criadoEm,amount:movementAmountV151(m),balance:m.saldoDepoisCentavos,orderNsu:c?.orderNsu||m.orderNsu||'',transactionNsu:c?.transactionNsu||''}}
function downloadParentReceiptImageV156(){const r=receiptLinesV156();if(!r)return;const canvas=document.createElement('canvas');canvas.width=1080;canvas.height=1280;const x=canvas.getContext('2d');x.fillStyle='#fff';x.fillRect(0,0,1080,1280);x.fillStyle='#2C3896';x.fillRect(0,0,1080,34);x.font='700 46px Barlow,Arial';x.fillText('ESCOLA PIAGET',70,120);x.fillStyle='#FF981F';x.fillRect(70,150,90,8);x.fillStyle='#172033';x.font='700 38px Barlow,Arial';x.fillText('Comprovante',70,235);const rows=[['Movimentação',r.title],['Aluno',r.student],['Matrícula',r.matricula],['Data',humanDate(r.date)],['Valor',signedV151(r.amount)],['Saldo após',r.balance!==undefined?signedV151(r.balance):'-'],['NSU do pedido',r.orderNsu||'-'],['NSU da transação',r.transactionNsu||'-']];let y=330;x.font='500 25px Barlow,Arial';for(const [a,b] of rows){x.fillStyle='#687189';x.fillText(a,70,y);x.fillStyle='#172033';x.font='700 28px Barlow,Arial';for(const [i,line] of String(b).match(/.{1,52}/g).entries())x.fillText(line,350,y+i*34);x.font='500 25px Barlow,Arial';y+=105}x.fillStyle='#687189';x.font='500 21px Barlow,Arial';x.fillText('Comprovante interno do Sistema de Vendas Escola Piaget.',70,1190);const a=document.createElement('a');a.download=`comprovante-piaget-${r.orderNsu||Date.now()}.png`;a.href=canvas.toDataURL('image/png');a.click()}
function downloadParentReceiptPdfV156(){const r=receiptLinesV156();if(!r||!window.jspdf)return;const {jsPDF}=window.jspdf,pdf=new jsPDF({unit:'mm',format:'a4'});pdf.setFillColor(44,56,150);pdf.rect(0,0,210,8,'F');pdf.setTextColor(44,56,150);pdf.setFont('helvetica','bold');pdf.setFontSize(18);pdf.text('Escola Piaget — Comprovante',15,23);pdf.setDrawColor(255,152,31);pdf.setLineWidth(1.5);pdf.line(15,28,40,28);pdf.setTextColor(30);pdf.setFontSize(11);let y=42;for(const [a,b] of [['Movimentação',r.title],['Aluno',r.student],['Matrícula',r.matricula],['Data',humanDate(r.date)],['Valor',signedV151(r.amount)],['Saldo após',r.balance!==undefined?signedV151(r.balance):'-'],['NSU do pedido',r.orderNsu||'-'],['NSU da transação',r.transactionNsu||'-']]){pdf.setFont('helvetica','bold');pdf.text(`${a}:`,15,y);pdf.setFont('helvetica','normal');pdf.text(pdf.splitTextToSize(String(b),135),55,y);y+=13}pdf.save(`comprovante-piaget-${r.orderNsu||Date.now()}.pdf`)}
async function openParentProgramsV156(){const a=state.parentStudent;openModal('Programação de lanches','<div class="v151-inline-loader">Carregando programação...</div>');try{const [pSnap,oSnap]=await Promise.all([db.collection('pedidos').where('alunoId','==',a.id).get(),db.collection('ocorrencias_entrega').where('alunoId','==',a.id).get()]),orders=pSnap.docs.map(d=>({id:d.id,...d.data()})).filter(x=>x.tipoPedido==='cantina'),occ=oSnap.docs.map(d=>({id:d.id,...d.data()})),active=orders.filter(o=>occ.some(x=>x.pedidoId===o.id&&!FINAL_DELIVERY_V151.includes(x.status)&&x.dataChave>=dateKey()));$('#modalBody').innerHTML=active.length?`<div class="v151-list">${active.map(o=>{const future=occ.filter(x=>x.pedidoId===o.id&&!FINAL_DELIVERY_V151.includes(x.status)&&x.dataChave>=dateKey()).sort((x,y)=>x.dataChave.localeCompare(y.dataChave));return`<button class="v151-order-card v156-program-card" onclick="openParentProgramDetailV156('${o.id}')"><div><h4>${o.modalidade==='mensal'?'Programação mensal':o.modalidade==='semanal'?'Programação semanal':'Lanche programado'}</h4><p>${future.length} entrega(s) futura(s) · ${future[0]?datePtV151(future[0].dataChave):'-'}</p></div><span>Ver detalhes →</span></button>`}).join('')}</div>`:'<div class="empty">Nenhuma programação ativa.</div>';state.v156ProgramData={orders,occ};}catch(e){$('#modalBody').innerHTML='<div class="alert danger">Não foi possível carregar a programação.</div>'}}
function programStatusV156(o){return statusLabelV151(o.status||'pendente_entrega')}
async function openParentProgramDetailV156(orderId){let data=state.v156ProgramData;if(!data){await openParentProgramsV156();data=state.v156ProgramData}const order=data?.orders?.find(x=>x.id===orderId),rows=(data?.occ||[]).filter(x=>x.pedidoId===orderId).sort((a,b)=>a.dataChave.localeCompare(b.dataChave));if(!order)return;openModal('Detalhes da programação',`<div class="v156-program-summary"><strong>${esc(order.alunoNome||state.parentStudent.nome)}</strong><span>${rows.length} entrega(s) · ${fmt(order.totalCentavos||0)}</span></div><div class="v151-list">${rows.map(o=>{const future=o.dataChave>dateKey()&&!FINAL_DELIVERY_V151.includes(o.status);return`<div class="v156-program-day"><div><strong>${datePtV151(o.dataChave,true)}</strong><div class="muted">${(o.itens||[]).map(x=>`${x.quantidade}× ${esc(x.nome)}`).join(', ')||'-'} · ${fmt(o.valorCentavos||0)}</div><div style="margin-top:5px">${statusBadgeV151(o.status)}</div></div>${future?`<div class="actions"><button class="btn btn-outline" onclick="openRescheduleProgramV156('${o.id}','${o.dataChave}')">Alterar data</button><button class="btn btn-red" onclick="cancelProgramDayV156('${o.id}')">Cancelar</button></div>`:''}</div>`}).join('')}</div><div class="v1523-compact-help"><span>Entregas concluídas ou do dia atual não podem ser alteradas.</span>${infoButton('Alterações da programação','Datas futuras podem ser remarcadas conforme o estoque. Ao cancelar, o valor da entrega volta para a conta do aluno.')}</div>`)}
function openRescheduleProgramV156(id,current){openModal('Alterar data da entrega',`<div class="fg"><label>Nova data</label><input id="v156NewProgramDate" class="fi" type="date" min="${addDaysV150(dateKey(),1)}" value="${current}"></div><button class="btn btn-primary" style="width:100%" onclick="saveRescheduleProgramV156('${id}')">Salvar nova data</button>`)}
async function saveRescheduleProgramV156(id){const date=$('#v156NewProgramDate')?.value;if(!date)return;const response=await fetch('/api/gerenciar-programacao-lanche',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({acao:'remarcar',ocorrenciaId:id,novaData:date,alunoId:state.parentStudent.id,criadoPorId:'portal_responsavel',criadoPorNome:state.parentStudent.responsavelFinanceiro||'Responsável',criadoPorPerfil:'responsavel'})}),data=await response.json().catch(()=>({}));if(!response.ok)return appMessage(data.error||'Não foi possível alterar a data.');toast('Data alterada.');state.v156ProgramData=null;openParentProgramsV156()}
async function cancelProgramDayV156(id){if(!await appConfirm('O valor voltará para a conta do aluno e o item será liberado no estoque.',{title:'Cancelar entrega?',confirmLabel:'Cancelar e devolver valor',cancelLabel:'Manter entrega',danger:true}))return;const response=await fetch('/api/gerenciar-programacao-lanche',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({acao:'cancelar',ocorrenciaId:id,alunoId:state.parentStudent.id,criadoPorId:'portal_responsavel',criadoPorNome:state.parentStudent.responsavelFinanceiro||'Responsável',criadoPorPerfil:'responsavel'})}),data=await response.json().catch(()=>({}));if(!response.ok)return appMessage(data.error||'Não foi possível cancelar a entrega.');toast('Entrega cancelada e valor devolvido.');state.v156ProgramData=null;await renderParentPortal();openParentProgramsV156()}
